INSERT INTO steam_dwh.dim_date(date_key, full_date, day, month, month_name, quarter, year)
INSERT INTO steam_dwh.dim_country(country_code,country_name,region) SELECT country_code,country_name,region FROM steam_oltp.countries ON CONFLICT (country_code) DO UPDATE SET country_name=EXCLUDED.country_name, region=EXCLUDED.region;
INSERT INTO steam_dwh.dim_user(username,country_key,registration_date) SELECT u.username, dc.country_key, u.registration_date FROM steam_oltp.users u JOIN steam_oltp.countries c ON c.country_id=u.country_id JOIN steam_dwh.dim_country dc ON dc.country_code=c.country_code ON CONFLICT(username) DO UPDATE SET country_key=EXCLUDED.country_key, registration_date=EXCLUDED.registration_date;
INSERT INTO steam_dwh.dim_developer(developer_name,country_key) SELECT d.developer_name, dc.country_key FROM steam_oltp.developers d LEFT JOIN steam_oltp.countries c ON c.country_id=d.country_id LEFT JOIN steam_dwh.dim_country dc ON dc.country_code=c.country_code ON CONFLICT(developer_name) DO UPDATE SET country_key=EXCLUDED.country_key;
INSERT INTO steam_dwh.dim_publisher(publisher_name,country_key) SELECT p.publisher_name, dc.country_key FROM steam_oltp.publishers p LEFT JOIN steam_oltp.countries c ON c.country_id=p.country_id LEFT JOIN steam_dwh.dim_country dc ON dc.country_code=c.country_code ON CONFLICT(publisher_name) DO UPDATE SET country_key=EXCLUDED.country_key;
INSERT INTO steam_dwh.dim_game(game_slug,title,release_year,developer_key,publisher_key) SELECT g.game_slug,g.title,extract(year from g.release_date)::int, dd.developer_key, dp.publisher_key FROM steam_oltp.games g JOIN steam_oltp.developers d ON d.developer_id=g.developer_id JOIN steam_dwh.dim_developer dd ON dd.developer_name=d.developer_name JOIN steam_oltp.publishers p ON p.publisher_id=g.publisher_id JOIN steam_dwh.dim_publisher dp ON dp.publisher_name=p.publisher_name ON CONFLICT(game_slug) DO UPDATE SET title=EXCLUDED.title, release_year=EXCLUDED.release_year, developer_key=EXCLUDED.developer_key, publisher_key=EXCLUDED.publisher_key;
INSERT INTO steam_dwh.dim_genre(genre_name) SELECT genre_name FROM steam_oltp.genres ON CONFLICT(genre_name) DO NOTHING;
INSERT INTO steam_dwh.bridge_game_genre(game_key, genre_key, weight) SELECT dg.game_key, dge.genre_key, 1.0 / COUNT(*) OVER (PARTITION BY dg.game_key) AS weight FROM steam_oltp.game_genres gg JOIN steam_oltp.games g ON g.game_id=gg.game_id JOIN steam_dwh.dim_game dg ON dg.game_slug=g.game_slug JOIN steam_oltp.genres ge ON ge.genre_id=gg.genre_id JOIN steam_dwh.dim_genre dge ON dge.genre_name=ge.genre_name ON CONFLICT(game_key, genre_key) DO UPDATE SET weight=EXCLUDED.weight;
INSERT INTO steam_dwh.dim_game_price_scd(game_key,price,currency,valid_from,valid_to,is_current) SELECT dg.game_key, ph.price, ph.currency, ph.valid_from, ph.valid_to, ph.valid_to IS NULL FROM steam_oltp.price_history ph JOIN steam_oltp.games g ON g.game_id=ph.game_id JOIN steam_dwh.dim_game dg ON dg.game_slug=g.game_slug ON CONFLICT(game_key, valid_from) DO UPDATE SET price=EXCLUDED.price, currency=EXCLUDED.currency, valid_to=EXCLUDED.valid_to, is_current=EXCLUDED.is_current;
INSERT INTO steam_dwh.fact_sales(purchase_code,date_key,user_key,game_key,game_price_key,units_sold,gross_revenue,discount_amount,net_revenue) SELECT p.purchase_code, to_char(p.purchase_date,'YYYYMMDD')::int, du.user_key, dg.game_key, gp.game_price_key, 1, g.base_price, g.base_price - p.paid_amount, p.paid_amount FROM steam_oltp.purchases p JOIN steam_oltp.users u ON u.user_id=p.user_id JOIN steam_dwh.dim_user du ON du.username=u.username JOIN steam_oltp.games g ON g.game_id=p.game_id JOIN steam_dwh.dim_game dg ON dg.game_slug=g.game_slug LEFT JOIN steam_dwh.dim_game_price_scd gp ON gp.game_key=dg.game_key AND p.purchase_date >= gp.valid_from AND (gp.valid_to IS NULL OR p.purchase_date <= gp.valid_to) ON CONFLICT(purchase_code) DO NOTHING;
INSERT INTO steam_dwh.fact_user_activity(date_key,user_key,game_key,reviews_count,achievements_count,avg_rating) SELECT date_key, user_key, game_key, SUM(reviews_count), SUM(achievements_count), NULLIF(AVG(avg_rating),0) FROM (SELECT to_char(r.review_date,'YYYYMMDD')::int date_key, du.user_key, dg.game_key, 1 reviews_count, 0 achievements_count, r.rating::numeric avg_rating FROM steam_oltp.reviews r JOIN steam_oltp.users u ON u.user_id=r.user_id JOIN steam_dwh.dim_user du ON du.username=u.username JOIN steam_oltp.games g ON g.game_id=r.game_id JOIN steam_dwh.dim_game dg ON dg.game_slug=g.game_slug UNION ALL SELECT to_char(ua.earned_date,'YYYYMMDD')::int, du.user_key, dg.game_key, 0, 1, NULL FROM steam_oltp.user_achievements ua JOIN steam_oltp.users u ON u.user_id=ua.user_id JOIN steam_dwh.dim_user du ON du.username=u.username JOIN steam_oltp.achievements a ON a.achievement_id=ua.achievement_id JOIN steam_oltp.games g ON g.game_id=a.game_id JOIN steam_dwh.dim_game dg ON dg.game_slug=g.game_slug) x GROUP BY date_key,user_key,game_key ON CONFLICT(date_key,user_key,game_key) DO UPDATE SET reviews_count=EXCLUDED.reviews_count, achievements_count=EXCLUDED.achievements_count, avg_rating=EXCLUDED.avg_rating;
