SELECT DISTINCT to_char(d, 'YYYYMMDD')::int, d, extract(day from d)::int, extract(month from d)::int, trim(to_char(d,'Month')), extract(quarter from d)::int, extract(year from d)::int
FROM (SELECT purchase_date d FROM steam_oltp.purchases UNION SELECT review_date FROM steam_oltp.reviews UNION SELECT earned_date FROM steam_oltp.user_achievements UNION SELECT registration_date FROM steam_oltp.users) x ON CONFLICT (date_key) DO NOTHING;
